command:
set -euo pipefail
SHA=9ce349fd58ea9ede78d5abba9e2dcef759c11d5e
BRANCH=work/photomap-straighten-20260912
SPEC=frontend/e2e/visual/.tmp-centered-gallery-density.spec.ts
cleanup() { rm -f "$SPEC"; ./scripts/devctl.sh stop >/dev/null 2>&1 || true; }
trap cleanup EXIT
git fetch origin "$BRANCH"
test "$(git rev-parse origin/$BRANCH)" = "$SHA"
test "$(git rev-parse HEAD)" = "$SHA"
test -z "$(git status --porcelain)"
cat > "$SPEC" <<'EOF'
import { expect, test } from "@playwright/test";
import { appConfig, city, places } from "../fixtures/visualData";
import { API_URL } from "../support/config";
import { clickMapMarker } from "../support/mapInteractions";
import { mockSharedApi } from "../support/visualApi";

test("probe: centered gallery can lose clicked place after density reselection", async ({ page }) => {
  await page.setViewportSize({ height: 820, width: 1280 });
  const probeCity = { ...city, default_zoom: 11 };
  const target = {
    ...places[0],
    city: probeCity,
    city_id: probeCity.id,
    id: "density-edge-target",
    lat: city.lat,
    lon: 17.44,
    score: 0,
    slug: "density-edge-target",
    title: "Density edge target",
    weight: 1,
  };
  const competitor = {
    ...places[0],
    city: probeCity,
    city_id: probeCity.id,
    id: "density-edge-competitor",
    lat: city.lat,
    lon: 17.55,
    score: 100,
    slug: "density-edge-competitor",
    title: "Density edge competitor",
    weight: 5,
  };

  await mockSharedApi(page, [target, competitor], undefined, [probeCity]);
  await page.route(`${API_URL}/api/app-config`, (route) =>
    route.fulfill({
      json: {
        ...appConfig,
        map: {
          ...appConfig.map,
          fallback_center: { lat: city.lat, lon: city.lon },
          fallback_zoom: 11,
        },
      },
    }),
  );
  await page.route(`${API_URL}/api/places/${target.id}/photos`, (route) => route.fulfill({ json: [] }));

  await page.goto("/");
  await expect(page.locator(`[title="${target.title}"]`)).toHaveCount(1);
  await expect(page.locator(`[title="${competitor.title}"]`)).toHaveCount(0);

  await clickMapMarker(page, target.title);

  await expect(page.locator(`[title="${competitor.title}"]`)).toHaveCount(1);
  await expect(page.locator(`[title="${target.title}"]`)).toHaveCount(0);
  await page.waitForTimeout(900);
  await expect(page.locator(".photo-gallery-marker")).toHaveCount(0);
});
EOF
VENV=$(mktemp -d /tmp/photomap-centered-gallery-density-XXXXXX)
python3 -m venv "$VENV"
"$VENV/bin/python" -m pip install -q -r backend/requirements.txt
cd frontend
PYTHON="$VENV/bin/python" npm run test:e2e -- e2e/visual/.tmp-centered-gallery-density.spec.ts --project=chromium
cd ..
rm -rf "$VENV"
cleanup
trap - EXIT
test -z "$(git status --porcelain)"
